function size(){const r=viewport.getBoundingClientRect();renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}
function move(target,distance,angle='default'){const directions={front:[0,.18,1],side:[1,.2,0],rear:[0,.18,-1],top:[0,1,.001],default:[1,.55,1.25]};camera.position.copy(target).add(new THREE.Vector3(...(directions[angle]||directions.default)).normalize().multiplyScalar(distance));controls.target.copy(target);controls.update();document.querySelectorAll('[data-angle]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.angle===angle)));}
