function closeup(kind){if(kind==='all'){fit();return;}const s=bounds.getSize(new THREE.Vector3()),c=bounds.getCenter(new THREE.Vector3());let target=c.clone(),radius=Math.max(s.x,s.y,s.z)*.24,angle='default';
 if(kind==='face'){target.y=bounds.min.y+s.y*.77;radius=s.y*.19;angle='front';}
 if(kind==='feet'){target.y=bounds.min.y+s.y*.12;radius=s.y*.15;angle='front';}
 if(kind==='body'){target.y=bounds.min.y+s.y*.4;radius=s.y*.26;angle='front';}
 if(kind==='nose'){target.z=bounds.max.z-s.z*.13;radius=Math.max(s.x*.32,s.z*.18);angle='default';}
 if(kind==='tail'){target.z=bounds.min.z+s.z*.13;radius=Math.max(s.x*.28,s.z*.2);angle='rear';}
 if(kind==='engine'){target.x=c.x+s.x*.15;target.y=bounds.min.y+s.y*.24;target.z=c.z+s.z*.16;radius=s.x*.2;angle='default';}
 if(kind==='wheel'){target.x=bounds.max.x-.1;target.y=bounds.min.y+s.y*.2;target.z=c.z+s.z*.28;radius=s.y*.25;angle='side';}
 if(kind==='side'){fit('side');return;}move(target,radius/Math.sin(THREE.MathUtils.degToRad(camera.fov/2))/Math.min(1,camera.aspect)*1.15,angle);}
